# The meeting is on Monday; times are represented as minutes since midnight.
DAY = "Monday"
WORK_START = 9 * 60
WORK_END = 17 * 60
DURATION = 30

# Constraint: each participant's existing meetings block those intervals.
busy = {
    "Judy": [],
    "Nicole": [
        (9 * 60, 10 * 60),
        (10 * 60 + 30, 16 * 60 + 30),
    ],
}

# Constraint: Nicole prefers not to meet before 16:00.
preferences = {
    "Nicole": lambda start: start >= 16 * 60,
}


def free_intervals(person):
    intervals = []
    cursor = WORK_START
    for start, end in sorted(busy[person]):
        if cursor < start:
            intervals.append((cursor, start))
        cursor = max(cursor, end)
    if cursor < WORK_END:
        intervals.append((cursor, WORK_END))
    return intervals


def intersect(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        start = max(a[i][0], b[j][0])
        end = min(a[i][1], b[j][1])
        if start < end:
            result.append((start, end))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return result


def satisfies_preferences(start):
    for person in busy:
        if person in preferences and not preferences[person](start):
            return False
    return True


common = None
for person in busy:
    person_free = free_intervals(person)
    common = person_free if common is None else intersect(common, person_free)

answer = None
for interval_start, interval_end in common:
    for start in range(interval_start, interval_end - DURATION + 1):
        if satisfies_preferences(start):
            answer = (start, start + DURATION)
            break
    if answer is not None:
        break

if answer is None:
    raise SystemExit("No valid meeting time found")

