def parse_time(value: str) -> int:
    hours, minutes = map(int, value.split(":"))
    return hours * 60 + minutes

def format_time(value: int) -> str:
    return f"{value // 60:02d}:{value % 60:02d}"

BUSY: Dict[str, Dict[str, List[Tuple[int, int]]]] = {
    "Jean": {
        "Monday": [],
