    for busy_start, busy_end in BUSY[person][day]:
        if start < busy_end and end > busy_start:
            return False
    return True

def works_for_everyone(day: str, start: int, end: int) -> bool:
    if day == "Monday" and end > NO_MEETING_AFTER:
        return False
    return all(is_free(person, day, start, end) for person in ("Jean", "Doris"))

